@startuml

class Product {
  + name : string
  + description : string
  + netPrice : double
}

class Manufacturer {
  + name : string
}

class Country {
  + name : string
  + vatRate : double
  + currency : string
  + conversionRateToEuro : double
}

class Representative {
  + firstName : string
  + lastName : string
  + socialSecurityNumber : string
  + telephoneNumber : string
  + emailAddress : string
}

class Customer {
  + name : string
  + address : string
  + telephoneNumber : string
  + emailAddress : string
}

class Order {
  + orderId : string
  + quantity : int
  + orderDate : date
  + desiredDeliveryDate : date
}

Manufacturer "1" -- "0..*" Product : manufactures
Country "1" -- "0..*" Product : availableIn
Representative "1" -- "1" Country : responsibleFor
Representative "1" -- "0..*" Order : places
Customer "1" -- "0..*" Order : places
Customer "0..*" -- "0..*" Country : resellsIn
Order "0..*" -- "1" Product : refersTo

@enduml

